//! The parts of the generated files that are not types.

use std::fmt::Write as _;

use super::RustArgs;

/// Start of a generated module: what it is, and what it uses.
pub(super) fn header(version: &str, from: &str, args: &RustArgs, packet: bool) -> String {
    module_header(version, from, &None, args, packet)
}

/// [`header`], with `doc` as the module's documentation.
pub(super) fn module_header(version: &str, from: &str, doc: &Option<String>, args: &RustArgs, packet: bool) -> String {
    let mut out = String::new();
    writeln!(out, "// @generated by IDL v{} from {}. Do not edit.", version, from).unwrap();
    if let Some(doc) = doc {
        for line in doc.lines().map(str::trim).filter(|l| !l.is_empty()) {
            writeln!(out, "//! {}", line).unwrap();
        }
    }
    writeln!(out, "#![allow(unused_imports, unused_mut, unused_variables, unreachable_patterns)]\n").unwrap();
    writeln!(
        out,
        "use {}::{{BString, Packet, PacketType, Reader, Wire, WireError, Writer}};",
        args.runtime_path
    )
    .unwrap();
    if packet {
        writeln!(out, "use {}::*;", args.shared_types_path).unwrap();
    }
    if let Some(samples) = &args.samples {
        writeln!(out, "#[cfg(feature = \"{}\")]\nuse {}::{{Gen, Sample}};", args.samples_feature, samples).unwrap();
    }
    out.push('\n');
    out
}

/// `mod.rs`: the modules, and a macro to go over every packet.
pub(super) fn index(version: &str, modules: &[(String, String)], definitions: &[String]) -> String {
    let mut out = String::new();
    writeln!(out, "// @generated by IDL v{}. Do not edit.\n", version).unwrap();
    writeln!(out, "pub mod shared_types;").unwrap();
    for module in definitions {
        writeln!(out, "pub mod {};", module).unwrap();
    }
    for (module, _) in modules {
        writeln!(out, "pub mod {};", module).unwrap();
    }
    writeln!(out, "\n/// Calls the macro `$m` with the path of every packet type, as").unwrap();
    writeln!(out, "/// `module::Type`, separated by commas.").unwrap();
    writeln!(out, "#[allow(unused_macros)]\nmacro_rules! for_each_packet {{\n    ($m:ident) => {{\n        $m! {{").unwrap();
    for (module, class) in modules {
        writeln!(out, "            {}::{},", module, class).unwrap();
    }
    writeln!(out, "        }}\n    }};\n}}\n#[allow(unused_imports)]\npub(crate) use for_each_packet;").unwrap();
    out
}
